/* Standalone embedding tests. No Fibril code is generated by this executable. */
#include <Python.h>
#include <stdio.h>
#include <string.h>
#include "bridge.h"

static int failures = 0;

static void check(int condition, const char *name) {
    if (!condition) { fprintf(stderr, "FAIL: %s\n", name); failures++; }
}

int main(void) {
    char error[256];
    double value = 123.0;
    check(fibril_py_call_double("math", "sqrt", 9, &value, error, sizeof error)
          == FIBRIL_PY_NOT_READY, "uninitialized interpreter rejected");

    /* Isolated initialization avoids ambient PYTHONPATH/current-directory
     * imports in this test. It is still not a sandbox for native extensions.
     */
    PyConfig config;
    PyConfig_InitIsolatedConfig(&config);
    PyStatus init = Py_InitializeFromConfig(&config);
    PyConfig_Clear(&config);
    if (PyStatus_Exception(init)) {
        fprintf(stderr, "Python initialization failed\n");
        return 1;
    }

    check(fibril_py_call_double("math", "sqrt", 9, &value, error, sizeof error)
          == FIBRIL_PY_OK && value == 3.0 && error[0] == '\0', "sqrt result");
    check(fibril_py_call_double("builtins", "abs", -4, &value, NULL, 0)
          == FIBRIL_PY_OK && value == 4.0, "optional error buffer");

    value = 123.0;
    check(fibril_py_call_double("math", "sqrt", -1, &value, error, sizeof error)
          == FIBRIL_PY_EXCEPTION && value == 123.0 && error[0] != '\0',
          "exception translated; output unchanged");
    check(!PyErr_Occurred(), "exception consumed");
    check(fibril_py_call_double("math", "pi", 1, &value, error, sizeof error)
          == FIBRIL_PY_EXCEPTION, "noncallable rejected");
    check(fibril_py_call_double("builtins", "str", 1, &value, error, sizeof error)
          == FIBRIL_PY_EXCEPTION, "nonnumeric result rejected");
    check(fibril_py_call_double("fibril_missing_module_7a3d", "f", 1, &value, error, sizeof error)
          == FIBRIL_PY_EXCEPTION, "missing module rejected");
    check(fibril_py_call_double("math", "missing_attribute_7a3d", 1, &value, error, sizeof error)
          == FIBRIL_PY_EXCEPTION, "missing attribute rejected");
    char tiny[1] = {'x'};
    check(fibril_py_call_double("math", "sqrt", -1, &value, tiny, sizeof tiny)
          == FIBRIL_PY_EXCEPTION && tiny[0] == '\0', "one-byte error buffer");
    check(fibril_py_call_double(NULL, "sqrt", 1, &value, error, sizeof error)
          == FIBRIL_PY_INVALID_ARGUMENT, "invalid arguments");
    PyErr_SetString(PyExc_ValueError, "pending");
    check(fibril_py_call_double("math", "sqrt", 1, &value, error, sizeof error)
          == FIBRIL_PY_NOT_READY && PyErr_ExceptionMatches(PyExc_ValueError),
          "pending caller exception preserved");
    PyErr_Clear();

    check(fibril_py_call_double("\xc3\xa9_fibril_missing", "f", 1, &value, error, sizeof error)
          == FIBRIL_PY_EXCEPTION, "Unicode exception formatting");
    for (size_t i = 0; error[i] != '\0'; i++) {
        check((unsigned char)error[i] < 128, "error buffer remains ASCII");
    }
    PyThreadState *state = PyEval_SaveThread();
    check(fibril_py_call_double("math", "sqrt", 1, &value, error, sizeof error)
          == FIBRIL_PY_NOT_READY, "caller without GIL rejected");
    PyEval_RestoreThread(state);

    /* Repeat ordinary success/failure cleanup paths; not a leak proof. */
    for (int i = 0; i < 100; i++) {
        check(fibril_py_call_double("math", "sqrt", 4, &value, error, sizeof error)
              == FIBRIL_PY_OK && value == 2.0, "repeated call");
        check(fibril_py_call_double("math", "sqrt", -1, &value, error, sizeof error)
              == FIBRIL_PY_EXCEPTION, "repeated failure");
    }
    if (Py_FinalizeEx() < 0) failures++;
    if (failures) return 1;
    puts("CPython embedding experiment passed (not Fibril FFI integration).");
    return 0;
}
